import clsx from 'clsx';
import React, {
  forwardRef,
  useEffect,
  useImperativeHandle,
  useRef,
  type ElementRef,
} from 'react';
import { useIntl } from 'react-intl';

import { DateRangeSelector } from './DateRangeSelector.js';
import { DateTimeInput } from './DateTimeInput.js';
import { dateTimeRangeCSS } from './DateTimeRangePicker.sty.js';
import { useDateTimeRangePicker } from './hooks/useDateTimeRangePicker.js';
import {
  DateRangeSelectorRef,
  DateTimeInputRef,
  type DateTimeRangePickerProps,
  type DateTimeRangePickerRef,
} from './types.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { textStyleCSS } from '../../styles/textStyle.sty.js';
import { _useFormFieldContext } from '../forms-core/hooks/useFormFieldContext.js';
import { FormFieldAction } from '../forms-core/state/formfield-state-reducer.js';

/**
 *  Component to comfortably enter a timeframe in localized format for expressions.
 * @internal
 */
export const DateTimeRangePicker = forwardRef<
  DateTimeRangePickerRef,
  DateTimeRangePickerProps
>((props, forwardedRef) => {
  const {
    id,
    precision = 'minutes',
    disabled = false,
    readOnly = false,
    name,
    style,
    className,
    min,
    max,
    required,
    'data-testid': dataTestId,
    'aria-label': ariaLabel,
    'aria-labelledby': ariaLabelledBy,
    'aria-describedby': ariaDescribedBy,
    'aria-details': ariaDetails,
  }: DateTimeRangePickerProps = props;

  const rootRef = useRef<ElementRef<'div'>>(null);
  const touchedRef = useRef<ElementRef<'div'>>(null);
  const dateTimeFromRef = useRef<DateTimeInputRef>(null);
  const dateTimeToRef = useRef<DateTimeInputRef>(null);
  const dateRangeSelectorRef = useRef<DateRangeSelectorRef>(null);

  // Provide root and input element reference and functions to interact with the calendar overlay
  useImperativeHandle(
    forwardedRef,
    () => ({
      element: rootRef.current,
      inputRef: {
        from: dateTimeFromRef.current?.inputRef,
        to: dateTimeToRef.current?.inputRef,
      },
      open: () => dateRangeSelectorRef.current?.open(),
      close: () => dateRangeSelectorRef.current?.close(),
      focus: () => dateTimeFromRef.current?.focus?.(),
    }),
    [],
  );

  const {
    value,
    onChange,
    placeholder,
    error,
    onCopyCaputure,
    onPasteCapture,
    onBlurTouched,
    onError,
  } = useDateTimeRangePicker(props, touchedRef);
  const intl = useIntl();

  const variantStyle = dateTimeRangeCSS({ error: error !== null, disabled });

  const { focusClassName } = useFocusRing({
    focusWithin: true,
    isMinimal: false,
    disabled,
    variant: error ? 'critical' : 'neutral',
  });

  const dateTimeFromLabel = intl.formatMessage({
    defaultMessage: 'DateTime from',
    id: 'fMy6q/KKOqbvCA3H',
    description:
      'Textbox to enter a relative or absolute timeframe from value.',
  });

  const dateTimeToLabel = intl.formatMessage({
    defaultMessage: 'DateTime to',
    id: 'uuhhc3nEZptwtV2E',
    description: 'Textbox to enter a relative or absolute timeframe to value.',
  });

  const { controlId, dispatch: formFieldContextDispatch } =
    _useFormFieldContext();

  useEffect(() => {
    formFieldContextDispatch?.({
      type: FormFieldAction.UPDATE,
      payload: {
        id,
        disabled,
        required,
      },
    });
  }, [disabled, formFieldContextDispatch, id, required]);

  return (
    <Flex
      ref={rootRef}
      flexDirection="column"
      data-testid={dataTestId}
      style={style}
      className={className}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledBy}
      aria-describedby={ariaDescribedBy}
      aria-details={ariaDetails}
    >
      <Flex gap={2} alignItems="center">
        <Flex
          ref={touchedRef}
          className={clsx(
            textStyleCSS({ textStyle: 'base' }),
            focusClassName,
            variantStyle,
          )}
          onCopyCapture={onCopyCaputure}
          onPasteCapture={onPasteCapture}
          onBlur={onBlurTouched}
        >
          <DateTimeInput
            ref={dateTimeFromRef}
            precision={precision}
            disabled={disabled}
            readOnly={readOnly}
            placeholder={placeholder.from}
            name={name !== undefined ? `${name}-from` : undefined}
            value={value.from}
            onChange={onChange.from}
            aria-label={dateTimeFromLabel}
            min={min}
            max={max}
            required={required}
            onError={onError.from}
            controlId={controlId}
          />
          <span>→</span>
          <DateTimeInput
            ref={dateTimeToRef}
            precision={precision}
            disabled={disabled}
            readOnly={readOnly}
            placeholder={placeholder.to}
            name={name !== undefined ? `${name}-to` : undefined}
            value={value.to}
            onChange={onChange.to}
            aria-label={dateTimeToLabel}
            min={min}
            max={max}
            required={required}
            onError={onError.to}
          />
        </Flex>
        <DateRangeSelector
          ref={dateRangeSelectorRef}
          value={error ? null : value} // if the component in in an error state, pass null to the calendar for a fresh start
          onChange={(selectedRange) => {
            const newFrom = selectedRange?.from ?? null;

            onChange.from(newFrom);
            onChange.to(selectedRange?.to ?? null);
          }}
          disabled={disabled}
          readOnly={readOnly}
          error={error !== null}
          min={min}
          max={max}
        />
      </Flex>
    </Flex>
  );
});
